namespace DeskNote {
public static class ThemePalette {
 public static Color Color(string value,string fallback){try{return (Color)ColorConverter.ConvertFromString(value);}catch{return (Color)ColorConverter.ConvertFromString(fallback);}}
 public static Color Blend(Color a,Color b,double t){return System.Windows.Media.Color.FromRgb((byte)(a.R*(1-t)+b.R*t),(byte)(a.G*(1-t)+b.G*t),(byte)(a.B*(1-t)+b.B*t));}
 public static bool IsLight(string value){var c=Color(value,"#0F172A");return c.R*.299+c.G*.587+c.B*.114>170;}
}
public class SettingsWindow:Window {
 readonly DeskApp app;
 readonly StackPanel body=new StackPanel();
 readonly List<Button> tabs=new List<Button>();
 readonly TextBlock status=new TextBlock();
 readonly DispatcherTimer saveTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};
 int page;
 double backgroundValue,overallValue;
 bool pending;
 static readonly Brush Ink=B("#F1F5F9"),Muted=B("#A0AABC"),Accent=B("#38BDF8"),Line=B("#344052");
 static Brush B(string hex){return new SolidColorBrush(ThemePalette.Color(hex,"#0F172A"));}
 static TextBlock Text(string text,double size=12,Brush color=null){return new TextBlock{Text=text,FontSize=size,Foreground=color??Ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,7)};}
 static readonly ControlTemplate ButtonTemplate=(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='box' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='8' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='box' Property='Opacity' Value='.8'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='box' Property='BorderBrush' Value='#38BDF8'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.4'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");
 Button Button(string text,Action action,bool primary=false){var b=new Button{Content=text,Template=ButtonTemplate,Background=primary?Accent:B("#202C40"),Foreground=primary?B("#08253A"):Ink,BorderBrush=Line,BorderThickness=new Thickness(1),Padding=new Thickness(12,8,12,8),Margin=new Thickness(0,0,8,0),Cursor=Cursors.Hand,MinHeight=32};b.Click+=(s,e)=>app.Run(action);return b;}
 Border Card(UIElement child){return new Border{Background=B("#1E293B"),BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),Padding=new Thickness(16),Margin=new Thickness(0,0,0,16),Child=child};}
 StackPanel Section(string title,string description=null){var p=new StackPanel();p.Children.Add(Text(title,14));if(description!=null)p.Children.Add(Text(description,12,Muted));return p;}
 Preferences P{get{return app.Store.Data.Settings;}}
 public SettingsWindow(DeskApp application){
  app=application;Title="后台选项与个性化设置";Icon=Branding.WindowIcon;Width=720;Height=710;MinWidth=620;MinHeight=570;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.CanResizeWithGrip;Background=B("#0F172A");Foreground=Ink;FontFamily=new FontFamily("Microsoft YaHei UI");FontSize=12;WindowStartupLocation=WindowStartupLocation.CenterScreen;

  var shell=new Border{BorderBrush=B("#245371"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(15),Background=Background};Content=shell;
  var dock=new DockPanel();shell.Child=dock;
  var header=new Grid{Margin=new Thickness(24,20,20,18)};header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});header.ColumnDefinitions.Add(new ColumnDefinition());header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
  var emblem=new Border{Width=34,Height=34,Background=Accent,CornerRadius=new CornerRadius(9),Margin=new Thickness(0,0,12,0),Child=new TextBlock{Text="⚙",FontSize=20,Foreground=B("#08253A"),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center}};header.Children.Add(emblem);
  var title=new StackPanel();title.Children.Add(Text("后台选项与个性化设置",17));title.Children.Add(Text("定制桌面挂件主题、透明质感、壁纸及 Windows 便捷选项",11,Muted));Grid.SetColumn(title,1);header.Children.Add(title);
  var reset=Button("↶ 恢复默认",RestoreAppearance);reset.Background=Brushes.Transparent;reset.BorderThickness=new Thickness(0);reset.ToolTip="恢复主题、透明度和时钟外观，不改变账本或安全设置";Grid.SetColumn(reset,2);header.Children.Add(reset);
  var close=Button("×",Close);close.FontSize=21;close.Padding=new Thickness(8,0,8,0);close.Background=Brushes.Transparent;close.BorderThickness=new Thickness(0);Grid.SetColumn(close,3);header.Children.Add(close);DockPanel.SetDock(header,Dock.Top);dock.Children.Add(header);header.MouseLeftButtonDown+=(s,e)=>{if(e.ChangedButton==MouseButton.Left&&e.OriginalSource is TextBlock)DragMove();};
  var nav=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(15,8,8,8)};string[] names={"◉ 主题配色","☷ 透明与质感","▧ 桌面壁纸","◷ 时间与时钟","☀ 本地天气","♧ 提醒与音效","⚙ Windows"};
  for(int i=0;i<names.Length;i++){int index=i;var b=Button(names[i],()=>SelectPage(index));b.Padding=new Thickness(11,6,11,6);b.BorderThickness=new Thickness(0);b.MinHeight=29;tabs.Add(b);nav.Children.Add(b);}
  var navBorder=new Border{Background=B("#161F30"),BorderBrush=Line,BorderThickness=new Thickness(0,1,0,1),Child=new ScrollViewer{Content=nav,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled}};DockPanel.SetDock(navBorder,Dock.Top);dock.Children.Add(navBorder);
  var footer=new DockPanel{Margin=new Thickness(22,12,16,12)};var done=Button("完成并关闭",Close,true);DockPanel.SetDock(done,Dock.Right);footer.Children.Add(done);status.Text="设置即时生效，并自动保存到本地";status.Foreground=Muted;status.FontSize=11;status.VerticalAlignment=VerticalAlignment.Center;footer.Children.Add(status);var footerBorder=new Border{Background=B("#1E293B"),BorderBrush=Line,BorderThickness=new Thickness(0,1,0,0),Child=footer};DockPanel.SetDock(footerBorder,Dock.Bottom);dock.Children.Add(footerBorder);
  body.Margin=new Thickness(24,23,24,8);dock.Children.Add(new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});
  saveTimer.Tick+=(s,e)=>FlushAppearance();Closing+=(s,e)=>{try{FlushAppearance();}catch{e.Cancel=true;throw;}};Closed+=(s,e)=>{saveTimer.Stop();app.Panel.AppearancePreview=false;app.Panel.ApplyPreferences();};SelectPage(0);
 }
 void Commit(Action<Preferences> action){FlushAppearance();app.Store.Change(d=>action(d.Settings));status.Text="已保存 · 设置已生效";Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle,new Action(()=>app.Run(()=>{app.Panel.ApplyPreferences();app.Refresh();})));}
 void QueueAppearance(){pending=true;app.Panel.AppearancePreview=true;app.Panel.SetAppearance(backgroundValue,overallValue);status.Text="预览中 · 正在保存…";saveTimer.Stop();saveTimer.Start();}
 void FlushAppearance(){saveTimer.Stop();if(!pending)return;app.Store.Change(d=>{d.Settings.BackgroundOpacity=backgroundValue;d.Settings.Opacity=overallValue;});pending=false;app.Panel.AppearancePreview=false;status.Text="已保存 · 设置已生效";}
 internal void SelectPage(int index){FlushAppearance();page=index;body.Children.Clear();for(int i=0;i<tabs.Count;i++){tabs[i].Background=i==index?B("#183E56"):Brushes.Transparent;tabs[i].Foreground=i==index?Accent:Muted;}switch(index){case 0:ThemePage();break;case 1:TransparencyPage();break;case 2:WallpaperPage();break;case 3:ClockPage();break;case 4:WeatherPage();break;case 5:RemindersPage();break;default:WindowsPage();break;}}
 void RestoreAppearance(){Commit(p=>{p.ThemeName="曜石暗夜";p.AccentColor="#38BDF8";p.SurfaceColor="#0F172A";p.BackgroundOpacity=1;p.Opacity=1;p.ShowSeconds=true;p.ShowDayProgress=true;});SelectPage(page);}
 void ThemePage(){
  var heading=Text("✧  精选桌面主题预设",14);heading.FontWeight=FontWeights.SemiBold;body.Children.Add(heading);
  string[,] themes={{"曜石暗夜","深邃石板灰底色配澄澈天青强调色","#0F172A","#38BDF8"},{"晨雾米白","温润浅白底色配清透钴蓝强调色","#F7FAFC","#2563EB"},{"松针暗绿","北欧森林深绿底色配翠绿强调色","#0B1A15","#10B981"},{"琥珀暖灰","暖调石墨底色配琥珀金","#1A1712","#F59E0B"},{"暮光靛青","静谧靛色深底配柔光青蓝","#111529","#60A5FA"},{"无框悬浮","超低透明度，轻融入桌面壁纸","#090E17","#2DD4BF"}};
  var grid=new Grid{Margin=new Thickness(-5,3,-5,14)};for(int i=0;i<3;i++)grid.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<2;i++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
  for(int i=0;i<6;i++){int n=i;string name=themes[i,0],surface=themes[i,2],accent=themes[i,3];bool selected=P.ThemeName==name;bool light=ThemePalette.IsLight(surface);var textColor=light?B("#172131"):Ink;var content=new StackPanel{Margin=new Thickness(12,9,12,8)};var row=new DockPanel();var check=Text(selected?"✓":"",13,B(accent));DockPanel.SetDock(check,Dock.Right);row.Children.Add(check);var label=Text(name,12,textColor);label.FontWeight=FontWeights.SemiBold;row.Children.Add(label);content.Children.Add(row);var desc=Text(themes[i,1],11,light?B("#52627A"):B("#AEBBCD"));desc.MinHeight=26;content.Children.Add(desc);var dots=new StackPanel{Orientation=Orientation.Horizontal};foreach(string hex in new[]{accent,surface})dots.Children.Add(new Border{Width=13,Height=13,Background=B(hex),BorderBrush=B("#627086"),BorderThickness=new Thickness(.6),CornerRadius=new CornerRadius(7),Margin=new Thickness(0,1,6,0)});content.Children.Add(dots);
   var button=Button("",()=>{Commit(p=>{p.ThemeName=name;p.AccentColor=accent;p.SurfaceColor=surface;p.BackgroundOpacity=n==5?.12:1;p.Opacity=1;});SelectPage(0);});button.Content=content;button.Padding=new Thickness(0);button.Margin=new Thickness(5,5,5,5);button.Background=B(surface);button.BorderBrush=selected?Accent:Line;button.BorderThickness=new Thickness(selected?3:1);button.HorizontalContentAlignment=HorizontalAlignment.Stretch;Grid.SetColumn(button,i%3);Grid.SetRow(button,i/3);grid.Children.Add(button);
  }body.Children.Add(grid);
  var custom=Section("自由自定义颜色");Swatches(custom,"主题强调色 (Accent Color)",P.AccentColor,new[]{"#38BDF8","#3B82F6","#10B981","#2DD4BF","#F59E0B","#FB7185","#A78BFA","#F8FAFC"},true);Swatches(custom,"挂件底色 (Surface Background)",P.SurfaceColor,new[]{"#0F172A","#090E17","#0B1A15","#1A1712","#111529","#F8FAFC","#F2F2F0"},false);body.Children.Add(Card(custom));
 }
 void Swatches(StackPanel parent,string title,string current,string[] colors,bool accent){var line=new DockPanel{Margin=new Thickness(0,9,0,7)};var value=Text(current,11,Accent);DockPanel.SetDock(value,Dock.Right);line.Children.Add(value);line.Children.Add(Text(title,12));parent.Children.Add(line);var row=new WrapPanel();foreach(string hex in colors){string color=hex;var b=Button(String.Equals(current,hex,StringComparison.OrdinalIgnoreCase)?"✓":"",()=>{Commit(p=>{p.ThemeName="自定义";if(accent)p.AccentColor=color;else p.SurfaceColor=color;});SelectPage(0);});b.Width=28;b.Height=28;b.MinHeight=28;b.Padding=new Thickness(0);b.Margin=new Thickness(0,0,7,5);b.Background=B(hex);b.Foreground=ThemePalette.IsLight(hex)?B("#0F172A"):Ink;b.BorderBrush=current==hex?Accent:B("#64748B");b.ToolTip=hex;row.Children.Add(b);}row.Children.Add(Button(accent?"拾色器  ▣":"底色取色  ▣",()=>{using(var dialog=new Forms.ColorDialog()){var c=ThemePalette.Color(current,"#38BDF8");dialog.Color=System.Drawing.Color.FromArgb(c.R,c.G,c.B);if(dialog.ShowDialog()!=Forms.DialogResult.OK)return;string hex="#"+dialog.Color.R.ToString("X2")+dialog.Color.G.ToString("X2")+dialog.Color.B.ToString("X2");Commit(p=>{p.ThemeName="自定义";if(accent)p.AccentColor=hex;else p.SurfaceColor=hex;});SelectPage(0);}}));parent.Children.Add(row);}
 void Slider(StackPanel p,string title,double min,double value,Action<double> change){var label=Text(title+"  "+Math.Round(value*100)+"%",12);p.Children.Add(label);var slider=new System.Windows.Controls.Slider{Minimum=min,Maximum=1,Value=value,TickFrequency=.05,IsSnapToTickEnabled=true,Margin=new Thickness(0,5,0,20)};slider.ValueChanged+=(s,e)=>{label.Text=title+"  "+Math.Round(slider.Value*100)+"%";change(slider.Value);};p.Children.Add(slider);}
 void Toggle(StackPanel p,string title,bool value,Action<bool> change,string description=null){var box=new CheckBox{Content=title,IsChecked=value,Foreground=Ink,Margin=new Thickness(0,8,0,10),FontSize=13};box.Checked+=(s,e)=>change(true);box.Unchecked+=(s,e)=>change(false);p.Children.Add(box);if(description!=null)p.Children.Add(Text(description,11,Muted));}
 void Select(StackPanel p,string label,IEnumerable<string> values,string current,Action<string> change){p.Children.Add(Text(label));var combo=UI.Select(values,current);combo.Foreground=Ink;combo.Margin=new Thickness(0,3,0,18);combo.SelectionChanged+=(s,e)=>change(UI.Value(combo));p.Children.Add(combo);}
 void TransparencyPage(){backgroundValue=P.BackgroundOpacity;overallValue=P.Opacity;var p=Section("透明与桌面质感","调整时直接预览桌面面板，文字透明度与背景透明度可分别控制。");Slider(p,"背景不透明度",.1,backgroundValue,v=>{backgroundValue=v;QueueAppearance();});Slider(p,"整体不透明度",.35,overallValue,v=>{overallValue=v;QueueAppearance();});p.Children.Add(Text("降低背景不透明度可透出桌面内容；此版本不提供系统毛玻璃模糊。",11,Muted));body.Children.Add(Card(p));var mode=Section("面板显示与布局");Select(mode,"窗口显示模式",new[]{"普通窗口","始终置顶","嵌入桌面"},P.EmbedDesktop?"嵌入桌面":P.Topmost?"始终置顶":"普通窗口",v=>Commit(prefs=>{prefs.EmbedDesktop=v=="嵌入桌面";prefs.Topmost=v=="始终置顶";}));Toggle(mode,"锁定面板移动和缩放",P.LayoutLocked,v=>Commit(prefs=>prefs.LayoutLocked=v));body.Children.Add(Card(mode));}
 void WallpaperPage(){var p=Section("桌面壁纸","让挂件与喜欢的桌面背景搭配。壁纸由 Windows 管理。");p.Children.Add(Button("打开 Windows 壁纸设置",()=>System.Diagnostics.Process.Start("ms-settings:personalization-background"),true));p.Children.Add(new Border{Height=18});p.Children.Add(Text("在系统设置中选择图片、纯色或幻灯片；这里只调整壁纸入口，不自动替换你的当前桌面。",12,Muted));body.Children.Add(Card(p));var tips=Section("搭配建议");tips.Children.Add(Text("浅色壁纸适合「曜石暗夜」和「松针暗绿」；深色壁纸可尝试「晨雾米白」。想让面板更轻盈，可以降低背景不透明度。",13,Muted));body.Children.Add(Card(tips));}
 void ClockPage(){var p=Section("时间与时钟","时钟跟随 Windows 本地时间；周视图以周一开始。");Toggle(p,"显示时钟秒数",P.ShowSeconds,v=>Commit(prefs=>prefs.ShowSeconds=v));Toggle(p,"显示今日时间流逝进度",P.ShowDayProgress,v=>Commit(prefs=>prefs.ShowDayProgress=v));p.Children.Add(Button("打开 Windows 日期与时间",()=>System.Diagnostics.Process.Start("ms-settings:dateandtime")));body.Children.Add(Card(p));}
 void WeatherPage(){var p=Section("本地天气","按选择的城市显示实时温度与天气，每15分钟更新。");Select(p,"天气城市",new[]{"关闭天气"}.Concat(Weather.Cities.Keys),String.IsNullOrEmpty(P.WeatherCity)?"关闭天气":P.WeatherCity,v=>{Commit(prefs=>prefs.WeatherCity=v=="关闭天气"?"":v);app.Panel.UpdateWeather(true);});p.Children.Add(Button("立即刷新天气",()=>app.Panel.UpdateWeather(true),true));p.Children.Add(new Border{Height=17});p.Children.Add(Text("数据来源 Open-Meteo。只请求选定城市的坐标，不获取精确定位；断网时显示离线。",12,Muted));body.Children.Add(Card(p));}
 void RemindersPage(){var p=Section("提醒与音效");Toggle(p,"开启到期提醒",P.EnableReminders,v=>Commit(prefs=>prefs.EnableReminders=v),"关闭期间不发送提醒，重新开启后补查到期事项。");Toggle(p,"提醒时播放提示音",P.ReminderSound,v=>Commit(prefs=>prefs.ReminderSound=v),"应用附加提示音；系统通知声音仍遵循 Windows 设置。");p.Children.Add(Button("试听提示音",()=>System.Media.SystemSounds.Asterisk.Play()));body.Children.Add(Card(p));var privacy=Section("私人提醒与财务保护");Toggle(privacy,"桌面显示脱敏的私人提醒",P.PrivateOnDesktop,v=>Commit(prefs=>prefs.PrivateOnDesktop=v));Toggle(privacy,"财务窗口失去焦点时锁定",P.LockOnBlur,v=>Commit(prefs=>prefs.LockOnBlur=v));Select(privacy,"财务无操作自动锁定（分钟）",new[]{"1","3","5","10","15"},P.LockMinutes.ToString(),v=>Commit(prefs=>prefs.LockMinutes=int.Parse(v)));body.Children.Add(Card(privacy));}
 void WindowsPage(){var p=Section("Windows 便捷选项");Toggle(p,"登录 Windows 时自动启动",P.AutoStart||app.AutoStartEnabled(),v=>{bool old=app.AutoStartEnabled();try{app.SetAutoStart(v);Commit(prefs=>prefs.AutoStart=v);}catch{app.SetAutoStart(old);throw;}});Select(p,"隐藏并锁定快捷键：Ctrl + Alt +",new[]{"H","J","K","L"},((char)P.Hotkey).ToString(),v=>{Commit(prefs=>prefs.Hotkey=(int)v[0]);app.RegisterKey();});p.Children.Add(Button("找回面板（恢复位置与透明度）",()=>Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(app.RecoverPanel))));body.Children.Add(Card(p));var data=Section("本地数据","备忘、便签与财务数据始终保存在当前 Windows 用户下。");data.Children.Add(Text(app.Store.Folder,11,Muted));data.Children.Add(Button("打开数据文件夹",()=>System.Diagnostics.Process.Start(app.Store.Folder)));body.Children.Add(Card(data));}
}
}





